import { ColorPicker, type ColorPickerValueDetail } from '@absoluteui/components/color-picker';

const host = document.createElement('div');
document.body.append(host);
ColorPicker.create(host, {
  label: 'Brand color',
  name: 'brand',
  value: '#2563eb',
  required: true,
  contrastWith: '#ffffff',
  presets: [
    { value: '#2563eb', label: 'Blue' },
    { value: '#16a34a', label: 'Green' },
    { value: '#dc2626', label: 'Red' },
  ],
});
host.addEventListener('aui-change', (event) => {
  const { value } = (event as CustomEvent<ColorPickerValueDetail>).detail;
  if (value !== null) document.documentElement.style.setProperty('--brand', value);
});

import { ColorPicker } from '@absoluteui/components/color-picker';

const host = document.createElement('div');
document.body.append(host);
const recent: string[] = ['#0f172a', '#f59e0b80'];
const picker = ColorPicker.create(host, { label: 'Overlay', mode: 'inline', alpha: true, value: '#0f172acc', recent, format: 'rgb' });
host.addEventListener('aui-change', () => {
  const value = picker.value;
  if (value !== null && !recent.includes(value)) {
    recent.unshift(value);
    picker.update({ recent: recent.slice(0, 8) });
  }
});
